"""MXFP4 fused MoE for preshuffled weights: top-k routing, SiLU-gated gate/up GEMM, down GEMM and weighted combine.
Decode token counts run route-direct stage kernels without a routing sort, the ``_FOLD`` counts fold the sort and the
zeroing of ``out`` into stage one, and other counts run aiter's two-stage FlyDSL pipeline or AKLR's baseline.
"""

import functools

import flydsl.compiler as flyc
import flydsl.expr as fx
import torch
from aiter.ops.flydsl.kernels.buffer_ops import buffer_load
from aiter.ops.flydsl.kernels.moe_2stage_a16wmix.utils import _global_i32_buffer_tiles
from aiter.ops.flydsl.kernels.mxfp4_gemm1 import (
    _bm_constants,
    _global_i32_at,
    _global_i32_load,
    _global_scalar_tiles,
    _inline_e8m0,
    _layout_idx,
    _pkmax_u16,
    _scalar_store,
    _silu_mul_batch,
    _udiv,
    _umod,
)
from aiter.ops.flydsl.kernels.mxfp4_gemm2 import _issue_a_load_lds, saq_slot_bytes, tiling
from aiter.ops.flydsl.kernels.mxfp4_gemm_common import (
    _buffer_rsrc,
    _e8m0_from_amax,
    _fabs_f32,
    _gep1,
    _gep3,
    _global_base_ptr1,
    _global_ptr1,
    _inline_dpp_quad_amax,
    _lds_ptr3,
    _lds_swizzle_mask,
    _umax_i32,
    bq_bytes_for,
    bscale_bytes_for,
    k_half_for,
    k_tiles_total_for,
    kas_per_chunk_dw_for,
    kbs_per_expert_dw_for,
    kBS_stride_k0_dw,
    kbs_stride_n0_dw_for,
    kStages,
    lds_acc_bytes_for,
    num_n_blocks_for,
)
from aklr.ops.fused_moe.baseline import fused_moe_baseline
from flydsl._mlir import ir
from flydsl._mlir.dialects import arith, llvm
from flydsl._mlir.dialects import rocdl as rocdl_ods
from flydsl._mlir.extras import types as _T
from flydsl.expr import const_expr, gpu, range_constexpr, rocdl
from flydsl.expr.typing import ReductionOp, T
from flydsl.runtime.device import is_rdna_arch

_D = 6144  # model dim
_I = 512  # inter dim
_N1 = 2 * _I  # gate + up rows
_TOPK = 9


def _raw(v):
    if not isinstance(v, ir.Value) and hasattr(v, "ir_value"):
        return v.ir_value()
    return v


def _rsrc(addr):
    """Buffer resource over a raw device address (no bounds checking)."""
    flags = (7 << 12) | (4 << 15)
    if is_rdna_arch(None):
        flags |= (1 << 24) | (2 << 28)
    base = llvm.IntToPtrOp(ir.Type.parse("!llvm.ptr"), _raw(fx.Int64(addr))).result
    i32 = _T.i32()
    i16 = _T.i16()
    i64 = _T.i64()
    fl = arith.ConstantOp(i32, ir.IntegerAttr.get(i32, flags)).result
    stride = arith.ConstantOp(i16, ir.IntegerAttr.get(i16, 0)).result
    nrec = arith.ConstantOp(i64, ir.IntegerAttr.get(i64, 0xFFFFFFFF)).result
    return rocdl_ods.MakeBufferRsrcOp(ir.Type.parse("!llvm.ptr<8>"), base, stride, nrec, fl).result


def _ld4(rsrc, off):
    return fx.Vector(rocdl.raw_ptr_buffer_load(T.i32x4, rsrc, fx.Int32(off), fx.Int32(0)))


def _ld1(rsrc, off):
    return fx.Int32(rocdl.raw_ptr_buffer_load(T.i32, rsrc, fx.Int32(off), fx.Int32(0)))


def _st(rsrc, off, value):
    rocdl_ods.raw_ptr_buffer_store(_raw(value), rsrc, _raw(fx.Int32(off)), _raw(fx.Int32(0)))


def _st16(rsrc, off, value):
    _st(rsrc, off, arith.trunci(T.i16, _raw(fx.Int32(value))))


def _uniform(x):
    return fx.Int32(rocdl.readfirstlane(T.i32, _raw(fx.Int32(x))))


def _sload(addr, idx):
    """Scalar (SMEM) load of the i32 at addr + 4 * idx for a workgroup-uniform idx."""
    ptr = llvm.IntToPtrOp(ir.Type.parse("!llvm.ptr<4>"), _raw(fx.Int64(addr) + fx.Int64(idx) * 4)).result
    return fx.Int32(llvm.LoadOp(T.i32, ptr, alignment=4, invariant=True).res)


def _lds(base, off):
    ptr_ty = fx.PointerType.get(T.i8, fx.AddressSpace.Shared)
    return fx.to_llvm_ptr(fx.inttoptr(ptr_ty, fx.Int64(base + off)))


def _lds_ldf(base, off):
    return fx.Float32(llvm.LoadOp(T.f32, _lds(base, off)).res)


def _umax(a, b):
    return (fx.Uint32(a) > fx.Uint32(b)).select(a, b)


def _e8m0(amax_bits):
    """Biased e8m0 exponent of the reference's MXFP4 scale for an |amax| bit pattern."""
    am = amax_bits.bitcast(fx.Float32)
    am = (am > fx.Float32(1e-10)).select(am, fx.Float32(1e-10))
    bits = am.bitcast(fx.Int32)
    return ((bits >> 23) & 255) - 2 + ((bits & 0x7FFFFF) > 0x400000).select(fx.Int32(1), fx.Int32(0))


def _pack_fp4(vals, scale):
    """Eight floats to one dword of fp4 (element j in nibble j)."""
    q = fx.Int32(0)
    for j in range_constexpr(len(vals) // 2):
        q = fx.Int32(
            rocdl.cvt_scalef32_pk_fp4_f32(
                T.i32, _raw(q), _raw(vals[2 * j]), _raw(vals[2 * j + 1]), _raw(scale), j
            )
        )
    return q


def _bf16_bits(x):
    return fx.Int32(fx.BFloat16(x).bitcast(fx.Uint16))


def _quant8(v):
    """Eight bf16 (one i32x4 of packed pairs; 4 consecutive lanes per 32-value group) to
    (fp4 dword, e8m0 exponent of the group)."""
    v2i16 = ir.VectorType.get([2], ir.IntegerType.get_signless(16))
    m = None
    for k in range_constexpr(4):
        a = llvm.BitcastOp(v2i16, _raw(v[k] & 0x7FFF7FFF)).result
        m = a if m is None else arith.maxui(m, a)
    m = fx.Int32(llvm.BitcastOp(T.i32, m).result)
    peak = _umax(m << 16, m & fx.Int32(-65536))
    # quad_perm [1,0,3,2] and [2,3,0,1]
    for ctrl in (0xB1, 0x4E):
        peak = _umax(peak, fx.Int32(rocdl.update_dpp(T.i32, _raw(peak), _raw(peak), ctrl, 0xF, 0xF, True)))
    ex = _e8m0(peak)
    scale = (ex << 23).bitcast(fx.Float32)
    v2bf16 = ir.VectorType.get([2], ir.BF16Type.get())
    q = fx.Int32(0)
    for k in range_constexpr(4):
        q = fx.Int32(
            rocdl.cvt_scalef32_pk_fp4_bf16(
                T.i32, _raw(q), llvm.BitcastOp(v2bf16, _raw(v[k])).result, _raw(scale), k
            )
        )
    return q, ex


def _from_lane(x, src):
    return fx.Int32(rocdl.ds_bpermute(T.i32, _raw(src * 4), _raw(x)))


def _gather_operand(q, ex, first):
    """MFMA operand of the 128-value chunk whose 16 fp4 dwords sit in lanes first .. first + 15
    (lane first + 4 * g + j holds dword j of group g): (i32x4 of group lg, its e8m0)."""
    lane = fx.Int32(gpu.thread_id("x")) % 64
    src = first + (lane // 16) * 4
    av = fx.Vector.from_elements([_from_lane(q, src + j) for j in range_constexpr(4)], fx.Int32)
    return av, _from_lane(ex, src)


def _silu_mul_bf16(g, u):
    ep = fx.Float32(rocdl.exp2(T.f32, _raw(g * fx.Float32(-1.4426950408889634))))
    sig = fx.Float32(rocdl.rcp(T.f32, _raw(fx.Float32(1.0) + ep)))
    return fx.Float32(fx.BFloat16(g * sig * u))


def _store_inter(INTER, route, part, cb, tid, g, u, P):
    """Stage-1 result of one column: silu(g) * u as bf16, or (P > 1) the part's fp32 g and u."""
    if P == 1:
        _st16(_rsrc(INTER), (route * _I + cb * 16 + tid) * 2, _bf16_bits(_silu_mul_bf16(g, u)))
    else:
        o = ((route * P + part) * _N1 + cb * 16 + tid) * 2
        _st16(_rsrc(INTER), o, _bf16_bits(g))
        _st16(_rsrc(INTER), o + _I * 2, _bf16_bits(u))


def _load_inter(INTER, route, lane, P):
    """This lane's 8 consecutive intermediate values: one i32x4 of bf16 pairs, or (P > 1) per part the
    fp32 gate and up partial sums (4 i32x4: gate lo, gate hi, up lo, up hi)."""
    rs = _rsrc(INTER)
    if P == 1:
        return _ld4(rs, route * (_I * 2) + lane * 16)
    return [
        [_ld4(rs, ((route * P + p) * _N1 + gu * _I + lane * 8) * 2) for gu in range_constexpr(2)]
        for p in range_constexpr(P)
    ]


def _bf16_half(w, hi):
    return ((w & fx.Int32(-65536)) if hi else (w << 16)).bitcast(fx.Float32)


def _fold_inter(xa, P):
    """The parts added in part order, silu(gate) * up rounded to bf16 and packed as ``_load_inter``'s P = 1 form."""
    if P == 1:
        return xa
    hb = []
    for j in range_constexpr(8):
        g = None
        u = None
        for p in range_constexpr(P):
            gp = _bf16_half(xa[p][0][j // 2], j % 2)
            up = _bf16_half(xa[p][1][j // 2], j % 2)
            g = gp if g is None else g + gp
            u = up if u is None else u + up
        hb.append(_bf16_bits(_silu_mul_bf16(g, u)))
    return fx.Vector.from_elements([hb[2 * k] | (hb[2 * k + 1] << 16) for k in range_constexpr(4)], fx.Int32)


@functools.cache
def _stage1_kernel(W, P=1):
    """Route-direct gate/up GEMM: grid (routes * 32 * P), 64 * W threads; workgroup part p owns the
    K chunks [p * 48 / P, (p + 1) * 48 / P) of 128, wave w NCH of them. With P > 1 the fp32 gate and
    up sums of each part are stored for stage 2 to add."""
    K = _D
    N = _N1
    NCB = _I // 16
    NCH = K // 128 // (W * P)
    RED_BYTES = W * 2 * 16 * 4
    assert NCH * W * P * 128 == K and NCH % 2 == 0 and (K // 128 // P) % 2 == 0

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, RED_BYTES, 16]

    @flyc.kernel(known_block_size=[64 * W, 1, 1])
    def stage1(X: fx.Int64, IDS: fx.Int64, W1: fx.Int64, WS1: fx.Int64, INTER: fx.Int64):
        tid = fx.Int32(gpu.thread_id("x"))
        bid = fx.Int32(gpu.block_id("x"))
        route = bid // (NCB * P)
        cb = (bid // P) % NCB
        part = bid % P
        lane = tid % 64
        wave = _uniform(tid // 64)
        l16 = lane % 16
        lg = lane // 16
        tok = route // _TOPK
        x = _rsrc(X)
        k0 = part * (K // 128 // P) + wave * NCH
        # The activations do not depend on the expert: issue them ahead of the topk_ids round trip.
        NLD = (NCH * 16 + 63) // 64
        xa = [
            _ld4(
                x,
                tok * (K * 2)
                + k0 * 256
                + (j * 64 + (lane % (NCH * 16 - j * 64 if j * 64 + 64 > NCH * 16 else 64))) * 16,
            )
            for j in range_constexpr(NLD)
        ]
        e = _sload(IDS, route)
        w = _rsrc(W1)
        ws = _rsrc(WS1)
        cols = [cb * 16, _I + cb * 16]
        # Scales ahead of weights (vmcnt retires in order), all loads issued before any use.
        bs_raw = [
            _ld1(ws, e * (N * K // 32) + (n >> 5) * K + lg * 64 + l16 * 4 + ((k0 >> 1) + p) * 256)
            for p in range_constexpr(NCH // 2)
            for n in cols
        ]
        bv = [
            _ld4(w, e * (N * K // 2) + (n >> 4) * (K * 8) + (k0 + i) * 1024 + lane * 16)
            for i in range_constexpr(NCH)
            for n in cols
        ]
        rocdl.sched_barrier(0)
        xq = [_quant8(v) for v in xa]
        shift = (cb & 1) * 8
        bs = [b >> shift for b in bs_raw]
        accs = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range_constexpr(2)]
        for i in range_constexpr(NCH):
            q, ex = xq[(i * 16) // 64]
            av, ax = _gather_operand(q, ex, (i * 16) % 64)
            for t in range_constexpr(2):
                accs[t] = fx.Vector(
                    rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                        T.f32x4, [bv[i * 2 + t], av, accs[t], 4, 4, (i & 1) * 2, bs[(i >> 1) * 2 + t], 0, ax]
                    )
                )
        lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
        if l16 == 0:
            for t in range_constexpr(2):
                llvm.StoreOp(_raw(accs[t]), _lds(lb, ((wave * 2 + t) * 16 + lg * 4) * 4), alignment=16)
        gpu.barrier()
        if tid < 16:
            g = _lds_ldf(lb, tid * 4)
            u = _lds_ldf(lb, (16 + tid) * 4)
            for wv in range_constexpr(1, W):
                g = g + _lds_ldf(lb, ((wv * 2) * 16 + tid) * 4)
                u = u + _lds_ldf(lb, ((wv * 2 + 1) * 16 + tid) * 4)
            _store_inter(INTER, route, part, cb, tid, g, u, P)

    return stage1


@functools.cache
def _stage2_kernel(TN, P=1):
    """Down GEMM and route sum: grid (tokens * 384 / TN), 9 waves, wave r = route slot r; each
    workgroup owns TN adjacent 16-column tiles (one shared scale dword covers 32 columns)."""
    K = _I
    N = _D
    NCB = N // (16 * TN)
    C = 16 * TN

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, _TOPK * C * 4, 16]

    @flyc.kernel(known_block_size=[64 * _TOPK, 1, 1])
    def stage2(INTER: fx.Int64, IDS: fx.Int64, RW: fx.Int64, W2: fx.Int64, WS2: fx.Int64, OUT: fx.Int64):
        tid = fx.Int32(gpu.thread_id("x"))
        bid = fx.Int32(gpu.block_id("x"))
        tok = bid // NCB
        cb = bid % NCB
        lane = tid % 64
        wave = _uniform(tid // 64)
        route = tok * _TOPK + wave
        l16 = lane % 16
        lg = lane // 16
        # Expert-independent loads first: this route's intermediate row and its routing weight.
        xa = _load_inter(INTER, route, lane, P)
        wt = _sload(RW, route).bitcast(fx.Float32)
        e = _sload(IDS, route)
        w = _rsrc(W2)
        ws = _rsrc(WS2)
        n = cb * C
        NS = (TN + 1) // 2
        bs_raw = [
            _ld1(ws, e * (N * K // 32) + ((n >> 5) + h) * K + lg * 64 + l16 * 4 + p * 256)
            for h in range_constexpr(NS)
            for p in range_constexpr(2)
        ]
        bv = [
            _ld4(w, e * (N * K // 2) + ((n >> 4) + t) * (K * 8) + kk * 1024 + lane * 16)
            for t in range_constexpr(TN)
            for kk in range_constexpr(4)
        ]
        rocdl.sched_barrier(0)
        xq, xe = _quant8(_fold_inter(xa, P))
        accs = [fx.Vector.filled(4, 0.0, fx.Float32) for _ in range_constexpr(TN)]
        for t in range_constexpr(TN):
            shift = ((cb & 1) * 8) if TN == 1 else (8 * (t & 1))
            bs = [b >> shift for b in bs_raw[(t >> 1) * 2 : (t >> 1) * 2 + 2]]
            for kk in range_constexpr(4):
                av, ax = _gather_operand(xq, xe, kk * 16)
                accs[t] = fx.Vector(
                    rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                        T.f32x4, [bv[t * 4 + kk], av, accs[t], 4, 4, (kk & 1) * 2, bs[kk >> 1], 0, ax]
                    )
                )
        lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
        if l16 == 0:
            for t in range_constexpr(TN):
                ov = fx.Vector.from_elements([accs[t][k] * wt for k in range_constexpr(4)], fx.Float32)
                llvm.StoreOp(_raw(ov), _lds(lb, (wave * C + t * 16 + lg * 4) * 4), alignment=16)
        gpu.barrier()
        if tid < C:
            s = _lds_ldf(lb, tid * 4)
            for r in range_constexpr(1, _TOPK):
                s = s + _lds_ldf(lb, (r * C + tid) * 4)
            _st16(_rsrc(OUT), (tok * N + n + tid) * 2, _bf16_bits(s))

    return stage2


# Token counts served by the two-launch route-direct path: (stage-1 waves per workgroup, stage-2
# 16-column tiles per workgroup, stage-1 K parts).
_DECODE = {1: (4, 2, 3), 2: (4, 4, 2), 4: (6, 2, 2)}


@functools.cache
def _plan(n_tokens):
    cfg = _DECODE.get(n_tokens)
    if cfg is None:
        return None
    W, TN, P = cfg
    s1 = _stage1_kernel(W, P)
    s2 = _stage2_kernel(TN, P)
    routes = n_tokens * _TOPK
    g1 = routes * (_I // 16) * P
    g2 = n_tokens * (_D // (16 * TN))

    @flyc.jit
    def launch(
        X: fx.Int64,
        IDS: fx.Int64,
        W1: fx.Int64,
        WS1: fx.Int64,
        W2: fx.Int64,
        WS2: fx.Int64,
        RW: fx.Int64,
        OUT: fx.Int64,
        INTER: fx.Int64,
        stream: fx.Stream,
    ):
        s1(X, IDS, W1, WS1, INTER).launch(grid=(g1, 1, 1), block=(64 * W, 1, 1), stream=stream)
        s2(INTER, IDS, RW, W2, WS2, OUT).launch(grid=(g2, 1, 1), block=(64 * _TOPK, 1, 1), stream=stream)

    # Kernel arguments arrive preloaded in SGPRs: the first loads need no kernarg s_load round trip.
    launch.compile_hints = {
        "llvm_options": {"amdgpu-kernarg-preload": True, "amdgpu-kernarg-preload-count": 16}
    }
    return launch


def _lds_add(lb, idx, val):
    """LDS atomic add of ``val`` to the i32 at index ``idx``; returns the old value."""
    return fx.Int32(
        llvm.AtomicRMWOp(
            llvm.AtomicBinOp.add,
            _lds(lb, fx.Int32(idx) * 4),
            _raw(fx.Int32(val)),
            llvm.AtomicOrdering.monotonic,
            syncscope="workgroup",
            alignment=4,
        ).result
    )


def _lds_ldi(lb, idx):
    return fx.Int32(llvm.LoadOp(T.i32, _lds(lb, fx.Int32(idx) * 4)).res)


def _lds_sti(lb, idx, v):
    llvm.StoreOp(_raw(fx.Int32(v)), _lds(lb, fx.Int32(idx) * 4), alignment=4)


_NE = 257
_RT = 512  # routing threads per workgroup


@functools.cache
def _route_kernel(n, bm, C, Z, Q=0):
    """Routing sort in one launch: workgroups 0 .. n / C - 1 each count all routes per expert in LDS (and those
    of earlier tokens), take the padded expert offsets from a scan, and place their own C tokens' routes in the
    expert's range ((slot << 24) | token, routing weight); workgroup w also writes the padding and block expert ids
    of experts w, w + G, ...; Z further workgroups zero ``out`` (Z = 0: no zeroing)."""
    G = n // C
    NV = n * _TOPK // 4
    NT = _RT
    R = C * _TOPK
    NOUT = n * _D * 2 // 16
    SENT = (_TOPK << 24) | n
    assert n % C == 0 and (n * _TOPK) % 4 == 0 and R <= NT and n // bm + 1 <= NT
    HIST, BEF, BASE, SCAN = 0, 512, 1024, 1536
    NU = n * _D // 8  # 8-value units of the activations
    QIT = (NU + Q * NT - 1) // (Q * NT) if Q else 0
    QB = 8  # units in flight per thread

    @fx.struct
    class Smem:
        raw: fx.Array[fx.Uint8, 1792 * 4, 16]

    @flyc.kernel(known_block_size=[NT, 1, 1])
    def route(
        IDS: fx.Int64,
        TW: fx.Int64,
        SID: fx.Int64,
        SW: fx.Int64,
        SEID: fx.Int64,
        NVI: fx.Int64,
        OUT: fx.Int64,
        X: fx.Int64,
        QO: fx.Int64,
        QS: fx.Int64,
    ):
        tid = fx.Int32(gpu.thread_id("x"))
        bid = fx.Int32(gpu.block_id("x"))
        lb = fx.Int32(fx.ptrtoint(fx.SharedAllocator().allocate(Smem).peek().raw.ptr))
        if const_expr(Q > 0):
            if bid >= G + Z:
                xr = _rsrc(X)
                qo = _rsrc(QO)
                qs = _rsrc(QS)
                for i0 in range_constexpr(0, QIT, QB):
                    us = [
                        (it * Q + (bid - (G + Z))) * NT + tid for it in range_constexpr(i0, min(i0 + QB, QIT))
                    ]
                    xs = [
                        _ld4(xr, (u if (i0 + k + 1) * Q * NT <= NU else (u < NU).select(u, fx.Int32(0))) * 16)
                        for k, u in enumerate(us)
                    ]
                    for k in range_constexpr(len(us)):
                        q, ex = _quant8(xs[k])
                        if us[k] < NU:
                            _st(qo, us[k] * 4, q)
                            if (tid & 3) == 0:
                                _st(qs, us[k] // 4, arith.trunci(ir.IntegerType.get_signless(8), _raw(ex)))
        if bid >= G:
            o = _rsrc(OUT)
            zero = fx.Vector.filled(4, 0, fx.Int32)
            for it in range_constexpr((NOUT + Z * NT - 1) // (Z * NT) if Z else 0):
                v = (it * Z + (bid - G)) * NT + tid
                if v < NOUT:
                    _st(o, v * 16, zero)
        if bid < G:
            ids = _rsrc(IDS)
            lim = bid * (C * _TOPK)
            _lds_sti(lb, HIST + tid, 0)
            _lds_sti(lb, BEF + tid, 0)
            xs = [
                _ld4(
                    ids,
                    (
                        (it * NT + tid)
                        if (it + 1) * NT <= NV
                        else ((it * NT + tid) < NV).select(it * NT + tid, fx.Int32(0))
                    )
                    * 16,
                )
                for it in range_constexpr((NV + NT - 1) // NT)
            ]
            gpu.barrier()
            for it in range_constexpr((NV + NT - 1) // NT):
                v = it * NT + tid
                if v < NV:
                    for j in range_constexpr(4):
                        _lds_add(lb, HIST + xs[it][j], 1)
                        if v * 4 + j < lim:
                            _lds_add(lb, BEF + xs[it][j], 1)
            gpu.barrier()
            i = tid & 255
            a = ((_lds_ldi(lb, HIST + 2 * i) + (bm - 1)) // bm) * bm
            b = ((_lds_ldi(lb, HIST + 2 * i + 1) + (bm - 1)) // bm) * bm
            s = a + b
            if tid < 256:
                _lds_sti(lb, SCAN + i, s)
            gpu.barrier()
            acc = s
            for d in (1, 2, 4, 8, 16, 32, 64, 128):
                other = _lds_ldi(lb, SCAN + (i >= d).select(i - d, fx.Int32(0)))
                acc = acc + (i >= d).select(other, fx.Int32(0))
                gpu.barrier()
                if tid < 256:
                    _lds_sti(lb, SCAN + i, acc)
                gpu.barrier()
            if tid < 256:
                _lds_sti(lb, BASE + 2 * i, acc - s)
                _lds_sti(lb, BASE + 2 * i + 1, acc - b)
            gpu.barrier()
            _lds_sti(lb, BEF + tid, _lds_ldi(lb, BEF + tid) + _lds_ldi(lb, BASE + tid))
            gpu.barrier()
            sid = _rsrc(SID)
            sw = _rsrc(SW)
            if tid < R:
                r = lim + tid
                e = _ld1(ids, r * 4)
                wt = _ld1(_rsrc(TW), r * 4)
                pos = _lds_add(lb, BEF + e, 1)
                _st(sid, pos * 4, ((r % _TOPK) << 24) | (r // _TOPK))
                _st(sw, pos * 4, wt)
            seid = _rsrc(SEID)
            for q in range_constexpr((_NE + G - 1) // G):
                e = bid + q * G
                if e < _NE:
                    base = _lds_ldi(lb, BASE + e)
                    cnt = _lds_ldi(lb, HIST + e)
                    nb = (cnt + (bm - 1)) // bm
                    if tid < nb * bm - cnt:
                        _st(sid, (base + cnt + tid) * 4, fx.Int32(SENT))
                        _st(sw, (base + cnt + tid) * 4, fx.Int32(0))
                    if tid < nb:
                        _st(seid, (base // bm + tid) * 4, e)
            if bid == 0:
                if tid == 0:
                    nv = _rsrc(NVI)
                    _st(nv, 0, _lds_ldi(lb, SCAN + 255))
                    _st(nv, 4, fx.Int32(n))

    @flyc.jit
    def launch(
        IDS: fx.Int64,
        TW: fx.Int64,
        SID: fx.Int64,
        SW: fx.Int64,
        SEID: fx.Int64,
        NVI: fx.Int64,
        OUT: fx.Int64,
        X: fx.Int64,
        QO: fx.Int64,
        QS: fx.Int64,
        stream: fx.Stream,
    ):
        route(IDS, TW, SID, SW, SEID, NVI, OUT, X, QO, QS).launch(
            grid=(G + Z + Q, 1, 1), block=(NT, 1, 1), stream=stream
        )

    return launch


# Token counts whose routing sort (and, for an atomic stage 2, the zeroing of ``out``) is ``_route_kernel``'s one
# launch: (tokens per routing workgroup, zeroing workgroups).
_ROUTE = {256: (2, 128), 512: (4, 128), 1024: (8, 128), 2048: (16, 128), 4096: (32, 128)}
# Token counts whose activation quant runs in the routing launch: quant workgroups.
_ROUTE_QUANT = {256: 384, 512: 384, 1024: 384, 2048: 384, 4096: 384}


def _stage2_fp8_reduce(
    inter_states,
    w1,
    w2,
    sorted_token_ids,
    sorted_expert_ids,
    num_valid_ids,
    out,
    topk,
    kernelName="",
    model_dim=0,
    inter_dim=0,
    num_experts=0,
    w2_scale=None,
    a2_scale=None,
    sorted_weights=None,
    bias2=None,
    inter_dim_pad=0,
    model_dim_pad=0,
    block_m=None,
    topk_weights=None,
    **_kwargs,
):
    """aiter's FlyDSL v2 stage 2 with a reduce epilogue, keeping the per-route partials in fp8 (row-blocked
    scales) instead of bf16; the routing weight is applied in the route reduction, which writes ``out``."""
    from aiter import fused_moe as fm
    from aiter.ops.flydsl.kernels.mxfp4_gemm_common import (
        FP8OUT_PITCH_ALIGN,
        fp8out_row_bytes,
        fp8out_scale_blk,
    )
    from aiter.ops.flydsl.kernels.mxmoe_dispatcher import mxfp4_moe_gemm2
    from aiter.ops.flydsl.moe_kernels import _run_moe_reduction

    if topk_weights is None or sorted_weights is None:
        raise ValueError("fp8 route partials need sorted_weights and topk_weights")
    cfg = fm.parse_flydsl_v2_gemm2_kernel(kernelName)
    bm = cfg["tile_m"]
    sbm = cfg["sort_block_m"] or (int(block_m) if block_m else bm)
    token_num, mdim = out.shape
    scale_blk = fp8out_scale_blk(mdim)
    target = torch.empty(
        (token_num * topk, fp8out_row_bytes(mdim, scale_blk=scale_blk, pitch_align=FP8OUT_PITCH_ALIGN)),
        dtype=torch.uint8,
        device=out.device,
    )
    mxfp4_moe_gemm2(
        inter_sorted_quant=fm._mxfp4_scale_u8(inter_states),
        inter_sorted_shuffled_scale=fm._mxfp4_scale_u8(a2_scale),
        w2_u8=fm._mxfp4_scale_u8(w2),
        w2_scale_u8=fm._mxfp4_scale_u8(w2_scale),
        sorted_expert_ids=sorted_expert_ids,
        cumsum_tensor=num_valid_ids,
        sorted_token_ids=sorted_token_ids,
        sorted_weights=sorted_weights,
        out=target,
        M_logical=token_num,
        max_sorted=inter_states.shape[0],
        NE=num_experts,
        D_HIDDEN=model_dim,
        D_INTER=inter_dim,
        topk=topk,
        BM=bm,
        BN=cfg["tile_n"],
        BK=cfg["tile_k"],
        use_nt=cfg["use_nt"],
        a_dtype=cfg["a_dtype"],
        b_dtype=cfg["b_dtype"],
        epilog="reduce",
        SBM=sbm,
        persist=cfg["persist"],
        inter_dim_pad=inter_dim_pad,
        model_dim_pad=model_dim_pad,
        g2_bf16_lds=cfg["bf16_lds"],
        g2_spart=cfg["spart"],
        out_dtype="fp8",
        bias=bias2,
    )
    _run_moe_reduction(
        target,
        out,
        token_num,
        topk,
        mdim,
        is_fp8=True,
        topk_weights=topk_weights,
        fp8_scale_blk=scale_blk,
        fp8_pitch_align=FP8OUT_PITCH_ALIGN,
    )
    return out


# Token counts whose reduce-epilogue stage 2 keeps fp8 route partials.
_FP8_REDUCE = frozenset({2048, 4096})


_S1 = "flydsl_moe1_afp4_wfp4_bf16_"
_S2 = "flydsl_moe2_layout_afp4_wfp4_bf16_"
# Token counts whose stage kernels differ from aiter's tuned pick, chosen from aiter's own kernel-name space by
# timing the whole call offline: (sort block_m, stage-1 kernel, stage-2 kernel). At 2048 and 4096 the reduce
# stage 2 runs unpersisted with 8-wide tile groups (sp802) so neighbouring workgroups share w2 panels in L2.
_OVERRIDE = {
    256: (32, _S1 + "t32x64x256_w3_kw2_fp4", _S2 + "t32x256x128_atomic_nt_sbm32"),
    512: (32, _S1 + "t32x64x256_w3_kw2_fp4", _S2 + "t32x256x128_atomic_nt_sbm32"),
    1024: (64, _S1 + "t64x128x256_w3_fp4", _S2 + "t64x128x128_atomic_persist_nt_sbm64"),
    2048: (128, _S1 + "t128x128x256_w2_fp4", _S2 + "t64x256x128_reduce_sbm128_sp802"),
    4096: (64, _S1 + "t64x128x256_w3_bnt0_xcd4_fp4", _S2 + "t64x256x128_reduce_sbm64_sp802"),
}

# Token counts on aiter's adaptive aux path (BM=16) whose stage kernels differ from aiter's tuned pick:
# (stage-1 mxmoe kernel, stage-2 kernel).
_AUX_OVERRIDE = {
    n: ("flydsl_mxmoe_g1_a4w4_16x256x256_f16in_nt", _S2 + "t16x128x256_atomic_nt_sbm16") for n in (8, 16)
}


def _fp8_transform(md):
    """Metadata transform swapping the bf16 reduce stage 2 for ``_stage2_fp8_reduce`` (a new object; the
    cached metadata aiter's own calls read is left untouched)."""
    import dataclasses

    s2 = md.stage2
    return dataclasses.replace(md, stage2=functools.partial(_stage2_fp8_reduce, *s2.args, **s2.keywords))


def _rename(stage, name):
    return functools.partial(stage.func, *stage.args, **{**stage.keywords, "kernelName": name})


def _kernels_transform(override, fp8, md):
    """Metadata transform naming other stage kernels (and the fp8 route partials where asked)."""
    import dataclasses

    if override is not None and override[0] == "aux":
        _, kn1, kn2 = override
        s1, s2 = md.stage1, md.stage2
        md = dataclasses.replace(
            md,
            stage1=functools.partial(s1.func, *s1.args, **{**s1.keywords, "kernelName1": kn1}),
            stage2=functools.partial(s2.func, *s2.args, **{**s2.keywords, "kernelName2": kn2}),
        )
    elif override is not None:
        bm, kn1, kn2 = override
        md = dataclasses.replace(
            md, stage1=_rename(md.stage1, kn1), stage2=_rename(md.stage2, kn2), block_m=bm
        )
    return _fp8_transform(md) if fp8 else md


@functools.cache
def _aiter_plan(n_tokens, w1_dtype, shuffled):
    """How aiter's fused_moe would sort and run this token count, mirrored so that its result is
    written straight into the caller's ``out``: (branch, block_m, metadata, q_dtype_a) or None.
    Branch "aux": adaptive aux sort (BM=16) zeroes ``out`` for the atomic stage 2; "atomic": opus
    sort zeroes ``out`` for the atomic stage 2; "reduce": stage 2's route reduction writes ``out``."""
    import aiter
    from aiter import ActivationType, QuantType
    from aiter import fused_moe as fm
    from aiter.fused_moe import GateMode

    q_dtype_a = aiter.dtypes.fp4x2
    md = fm.get_2stage_cfgs(
        fm.get_padded_M(n_tokens),
        _D,
        _I,
        257,
        _TOPK,
        torch.bfloat16,
        q_dtype_a,
        w1_dtype,
        QuantType.per_1x32,
        True,
        ActivationType.Silu,
        False,
        0,
        0,
        shuffled,
        GateMode.SEPARATED,
        is_ep=False,
        has_stage2_bias=False,
        opus_weights_shuffled=shuffled,
        config_file=None,
    )
    if md.run_1stage or md.flat or md.block_m is None:
        return None
    override = _OVERRIDE.get(n_tokens)
    if override is not None:
        if md.output_aux:
            return None
        md = _kernels_transform(override, False, md)
    bm = int(md.block_m)
    if md.output_aux:
        if fm._MOE_SORT_BACKEND in ("opus", "ck") or bm != 16:
            return None
        if not fm.parse_g2_kname_any(md.stage2.keywords.get("kernelName2", ""))["atomic"]:
            return None
        aux = _AUX_OVERRIDE.get(n_tokens)
        if aux is not None:
            md = _kernels_transform(("aux",) + aux, False, md)
            if not fm.parse_g2_kname_any(md.stage2.keywords.get("kernelName2", ""))["atomic"]:
                return None
        return "aux", bm, q_dtype_a, None if aux is None else ("aux",) + aux
    if fm._USE_CK_MOE_SORTING or fm._USE_FLYDSL_MOE_SORTING:
        return None
    if not fm.stage2_uses_route_reduce(md.stage2):
        return "atomic", bm, q_dtype_a, override
    s2 = md.stage2
    if (
        n_tokens in _FP8_REDUCE
        and getattr(s2, "func", None) is fm._flydsl_v2_stage2_wrapper
        and not s2.args
        and (fm.parse_flydsl_v2_gemm2_kernel(s2.keywords.get("kernelName", "")) or {}).get("epilog")
        == "reduce"
    ):
        return "reduce_fp8", bm, q_dtype_a, override
    return "reduce", bm, q_dtype_a, override


def _aiter_into_out(plan, hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, out):
    """aiter's two-stage fused MoE with ``out`` as its accumulator (no output copy)."""
    import aiter
    from aiter import ActivationType, QuantType
    from aiter import fused_moe as fm
    from aiter.fused_moe import GateMode

    branch, bm, q_dtype_a, override = plan
    dev = hidden_states.device
    M = topk_ids.shape[0]
    i32 = torch.int32
    m_indices = reverse_sorted = a1_scale = None
    if branch == "aux":
        active = min(257, M * _TOPK)
        max_sorted = (((M * _TOPK + active * (bm - 1)) + bm - 1) // bm) * bm
        sorted_ids = torch.empty(max_sorted, dtype=i32, device=dev)
        sorted_expert_ids = torch.empty(max_sorted // bm, dtype=i32, device=dev)
        num_valid_ids = torch.empty(2, dtype=i32, device=dev)
        sorted_weights = torch.empty(max_sorted, dtype=torch.float32, device=dev)
        reverse_sorted = torch.empty(M * _TOPK, dtype=i32, device=dev)
        m_indices = torch.empty(max_sorted, dtype=i32, device=dev)
        empty_bf16 = torch.empty((0,), dtype=torch.bfloat16, device=dev)
        aiter.mxfp4_moe_sort(
            topk_ids=topk_ids,
            topk_weight=topk_weights,
            sorted_token_ids=sorted_ids,
            sorted_expert_ids=sorted_expert_ids,
            cumsum_tensor=num_valid_ids,
            reverse_sorted=reverse_sorted,
            sorted_weights=sorted_weights,
            m_indices=m_indices,
            bf16_zero_out=out,
            bf16_zero_workspace=empty_bf16,
            sort3stage_ws=torch.empty(0, dtype=i32, device=dev),
            M_logical=M,
            NE=257,
            TOPK=_TOPK,
            D_HIDDEN=_D,
            D_INTER=1,
            MB=bm,
            prologue=0,
        )
    else:
        padded = M * _TOPK + 257 * bm - _TOPK
        sorted_ids = torch.empty(padded, dtype=i32, device=dev)
        sorted_weights = torch.empty(padded, dtype=torch.float32, device=dev)
        sorted_expert_ids = torch.empty((padded + bm - 1) // bm, dtype=i32, device=dev)
        num_valid_ids = torch.empty(2, dtype=i32, device=dev)
        if M in _ROUTE:
            C, Z = _ROUTE[M]
            Q = _ROUTE_QUANT.get(M, 0)
            if Q:
                a1 = torch.empty((M, _D // 2), dtype=aiter.dtypes.fp4x2, device=dev)
                a1_scale = torch.empty((M, _D // 32), dtype=aiter.dtypes.fp8_e8m0, device=dev)
                qargs = (hidden_states.data_ptr(), a1.data_ptr(), a1_scale.data_ptr())
                hidden_states = a1
            else:
                qargs = (0, 0, 0)
            _route_kernel(M, bm, C, Z if branch == "atomic" else 0, Q)(
                topk_ids.data_ptr(),
                topk_weights.data_ptr(),
                sorted_ids.data_ptr(),
                sorted_weights.data_ptr(),
                sorted_expert_ids.data_ptr(),
                num_valid_ids.data_ptr(),
                out.data_ptr(),
                *qargs,
                torch.cuda.current_stream(dev).cuda_stream,
            )
        else:
            moe_buf = out if branch == "atomic" else torch.empty((0, 0), dtype=torch.bfloat16, device=dev)
            ws_size = aiter.moe_sorting_opus_get_workspace_size(M, 257, _TOPK, 0)
            workspace = torch.empty(ws_size, dtype=torch.uint8, device=dev) if ws_size > 0 else None
            aiter.moe_sorting_opus_fwd(
                topk_ids,
                topk_weights,
                sorted_ids,
                sorted_weights,
                sorted_expert_ids,
                num_valid_ids,
                moe_buf,
                257,
                bm,
                None,
                None,
                workspace,
                0,
                None,
                None,
                None,
            )
    fp8 = branch == "reduce_fp8"
    fm.fused_moe_2stages(
        hidden_states,
        w1,
        w2,
        _TOPK,
        sorted_ids,
        sorted_weights,
        sorted_expert_ids,
        num_valid_ids,
        out,
        True,
        bm,
        activation=ActivationType.Silu,
        quant_type=QuantType.per_1x32,
        doweight_stage1=False,
        q_dtype_a=q_dtype_a,
        q_dtype_w=w1.dtype,
        w1_scale=w1_scale,
        w2_scale=w2_scale,
        a1_scale=a1_scale,
        topk_ids=topk_ids,
        topk_weights=topk_weights,
        gate_mode=GateMode.SEPARATED,
        m_indices=m_indices,
        reverse_sorted=reverse_sorted,
        _metadata_transform=(
            functools.partial(_kernels_transform, override, fp8) if fp8 or override is not None else None
        ),
        _stage2_extra_args={"topk_weights": topk_weights} if fp8 else None,
    )


# Token counts served by the folded two-launch path (routing sort and ``out`` zeroing folded into stage 1):
# token count -> (stage 1 runs each XCD's tiles as one contiguous run, stage 2 orders its tiles XCD-major).
_FOLD = {32: (True, True), 64: (False, False)}
_FBM = 16  # rows per expert block
_FBN = 256
_FBK = 256
_ALIGN = 256
_FT = 256  # threads per workgroup
_NXCD = 8
_NT = 2  # buffer cache policy of the streamed weights: nontemporal
_NO_BOUND = 0x7FFFFFF0  # buffer size of operands read only inside their written rows
_HPF = 2  # k-tiles that a hidden-state load runs ahead of its quantization
_TOK_BITS = 24  # a sorted id packs the route's topk slot above its token
_EPI_LANES = _FBN // 8  # lanes per row of the atomic epilogue, two columns per pass
_EPI_ROWS = _FT // _EPI_LANES  # rows per pass of the atomic epilogue
# Stage-1 sort scratch in LDS, in i32 words: expert histogram, wave totals, this block's expert and index within
# it, then the block's gather rows, sorted ids and routing weights.
_W_CNT = (_NE + 15) // 16 * 16
_W_WT = _W_CNT
_W_MISC = _W_WT + 16
_W_ROWS = _W_MISC + 16
_W_STOK = _W_ROWS + _FBM
_W_WGT = _W_STOK + _FBM
_SORT_WORDS = _W_WGT + _FBM


def _ashr(x, n):
    return fx.Int32(arith.ShRSIOp(_raw(x), _raw(fx.Int32(n))).result)


def _is_eq(a, b):
    """1 when a == b else 0, branch-free (a, b >= 0)."""
    return fx.Int32(0) - _ashr((a ^ b) - fx.Int32(1), 31)


def _lds_i32_tiles(base_ptr, word_off, n_words):
    flat = fx.make_view(
        fx.recast_iter(fx.Int32, fx.add_offset(base_ptr, word_off * 4)),
        fx.make_layout(n_words, 1),
    )
    return fx.logical_divide(flat, fx.make_layout(1, 1))


@flyc.jit
def _gemm1_body_fold(
    lds_raw_ptr,
    sort_lds_ptr,
    e,
    arg_bq,
    arg_bscale,
    arg_aqout,
    arg_ascaleout,
    arg_hidden,
    tile,
    lane,
    wave,
    i32_ntok,
    head_hook,
):
    """Gate/up GEMM of one (expert m-block, n-block) tile with the gathered activations quantized to MXFP4
    inline; writes silu(gate) * up as MXFP4 with shuffled e8m0 scales. ``head_hook`` runs the sort's rank and
    publish steps once the first weight stages are in flight."""
    K = _D
    N_OUT = _N1
    BM = _FBM
    BN = _FBN
    BK = _FBK
    KH_TILE = BK // 2
    K_HALF = k_half_for(K)
    KTP = k_tiles_total_for(K, BK)
    kUnroll = KTP - kStages
    kAStages = _bm_constants(BM, BN, KH_TILE, KTP)[0]
    kBS_stride_n0_dw = kbs_stride_n0_dw_for(K)
    kBS_per_expert_dw = kbs_per_expert_dw_for(N_OUT, K)
    NUM_N_BLOCKS = num_n_blocks_for(N_OUT, BN)
    NJ = BN // 64  # 16-column weight tiles per wave: 2 gate, 2 up
    W8 = BN // 8
    NTH = (BN // 2) // 8

    n_block_idx = tile % fx.Int32(NUM_N_BLOCKS)
    m_block_idx = tile // fx.Int32(NUM_N_BLOCKS)
    m_row = m_block_idx * fx.Int32(BM)

    lane_div_16 = lane // fx.Int32(16)
    lane_mod_16 = lane % fx.Int32(16)

    bq_tiles = _global_i32_buffer_tiles(arg_bq, bq_bytes_for(_NE, N_OUT, K), 4)
    bq_copy_atom = fx.make_copy_atom(fx.rocdl.BufferCopy128b(_NT), fx.Int32)
    bq_reg_lay = fx.make_layout(4, 1)

    bscale_tiles = _global_i32_buffer_tiles(arg_bscale, bscale_bytes_for(_NE, N_OUT, K), 1)
    bscale_copy_atom = fx.make_copy_atom(fx.rocdl.BufferCopy32b(_NT), fx.Int32)
    bscale_reg_lay = fx.make_layout(1, 1)

    hidden_tiles = _global_i32_buffer_tiles(arg_hidden, fx.Int64(i32_ntok * fx.Int32(K * 2)), 4)
    hidden_copy_atom = fx.make_copy_atom(fx.rocdl.BufferCopy128b(0), fx.Int32)
    hidden_reg_lay = fx.make_layout(4, 1)

    a_row = wave * fx.Int32(4) + lane_div_16

    N0_HALF = N_OUT // 32
    b_load_s_base = []
    for j in range_constexpr(NJ):
        # n0: this wave's gate column tile; j & 1 picks gate or up.
        g = fx.Int32(j & 1)
        n0 = n_block_idx * fx.Int32(BN // 32) + wave * fx.Int32(BN // 128) + fx.Int32(j >> 1)
        col = (g * fx.Int32(N0_HALF) + n0) * fx.Int32(16)
        v = (e * fx.Int32(N_OUT) + col) * fx.Int32(K_HALF)
        b_load_s_base.append(rocdl.readfirstlane(T.i32, v))

    # A weight-scale dword covers two adjacent column tiles, both owned by this wave.
    np_gate = (n_block_idx * fx.Int32(BN // 32) + wave * fx.Int32(BN // 128)) // fx.Int32(2)
    np_list = [np_gate, np_gate + fx.Int32(N_OUT // 64)]
    b_scale_s_base, b_scale_s_base_hi = [], []
    for mw in range_constexpr(2):
        base = (e * fx.Int32(kBS_per_expert_dw) + np_list[mw] * fx.Int32(kBS_stride_n0_dw)) * fx.Int32(4)
        base = rocdl.readfirstlane(T.i32, base)
        b_scale_s_base.append(base)
        b_scale_s_base_hi.append(base + fx.Int32(16 * kBS_stride_k0_dw * 4))

    accm = [None] * NJ
    b = [[[None, None] for _ in range(NJ)] for _ in range(kStages)]
    b_scale_v = [[None, None] for _ in range(kStages)]

    # LDS: kAStages quantized A tiles, then the A scales of every k-tile; reused as the f32 accumulator.
    s_aq_i32_flat = fx.make_view(
        fx.recast_iter(fx.Int32, lds_raw_ptr),
        fx.make_layout(kAStages * BM * KH_TILE // 4, 1),
    )
    s_aq_i32x4_tiles = fx.logical_divide(s_aq_i32_flat, fx.make_layout(4, 1))
    s_aq_i32x1_tiles = fx.logical_divide(s_aq_i32_flat, fx.make_layout(1, 1))
    i32x4_copy_atom = fx.make_copy_atom(fx.UniversalCopy128b(), fx.Int32)
    i32x4_reg_lay = fx.make_layout(4, 1)

    def _lds_i32x4_load(tile_idx):
        r = fx.make_rmem_tensor(i32x4_reg_lay, fx.Int32)
        fx.copy_atom_call(i32x4_copy_atom, fx.slice(s_aq_i32x4_tiles, (None, tile_idx)), r)
        return r.load()

    def issue_a_ds_read(slot):
        mask = _lds_swizzle_mask(lane_mod_16)
        a = [None, None]
        for k in range_constexpr(2):
            lds_col = (lane_div_16 * fx.Int32(16) + fx.Int32(k * 64)) ^ mask
            off = fx.Int32(slot * (BM * KH_TILE)) + lane_mod_16 * fx.Int32(KH_TILE) + lds_col
            a[k] = _lds_i32x4_load(off // fx.Int32(16))
        return a

    s_asc_i32_flat = fx.make_view(
        fx.recast_iter(fx.Int32, fx.add_offset(lds_raw_ptr, kAStages * BM * KH_TILE)),
        fx.make_layout(KTP * 64, 1),
    )
    asc_i32_tiles = fx.logical_divide(s_asc_i32_flat, fx.make_layout(1, 1))

    def issue_a_scale_ds_read(kt):
        lds_dw = fx.Int32(kt * 64) + lane_div_16 * fx.Int32(16) + lane_mod_16
        return _raw(_global_i32_load(asc_i32_tiles, lds_dw))

    lib = lane & fx.Int32(3)
    lane_shr2_and3 = (lane >> fx.Int32(2)) & fx.Int32(3)

    def hidden_load(half, kt, row_token):
        v_voff = row_token * fx.Int32(K * 2) + lane_shr2_and3 * fx.Int32(64) + lib * fx.Int32(16)
        s_soff = rocdl.readfirstlane(T.i32, fx.Int32(kt * (BK * 2) + half * BK))
        r = fx.make_rmem_tensor(hidden_reg_lay, fx.Int32)
        fx.copy(
            hidden_copy_atom,
            fx.slice(hidden_tiles, (None, v_voff // fx.Int32(16))),
            r,
            soffset=s_soff // fx.Int32(4),
        )
        return r.load()

    def hidden_loads(kt, row_token):
        return [hidden_load(0, kt, row_token), hidden_load(1, kt, row_token)]

    def quantize_tile(h_v, slot, kt):
        """A k-tile of bf16 activations, both halves of it, to MXFP4 in LDS slot ``slot`` and its scales."""
        h_dw = [[fx.Int32(_raw(h[j])) for j in range_constexpr(4)] for h in h_v]
        a = []
        for i in range_constexpr(2):
            hm = [h_dw[i][j] & fx.Int32(0x7FFF7FFF) for j in range_constexpr(4)]
            m0123 = _pkmax_u16(_pkmax_u16(hm[0], hm[1]), _pkmax_u16(hm[2], hm[3]))
            lo = m0123 & fx.Int32(0xFFFF)
            hi = m0123.shrui(fx.Int32(16)) & fx.Int32(0xFFFF)
            a.append(_inline_dpp_quad_amax(fx.Int32(_raw(_umax_i32(lo, hi)))))
        e8 = [_inline_e8m0(a[i]) for i in range_constexpr(2)]
        mask = _lds_swizzle_mask(a_row)
        scale_accum = fx.Int32(0)
        for i in range_constexpr(2):
            qs_raw = _raw(fx.Float32(_raw(e8[i] << fx.Int32(23)).bitcast(T.f32)))
            pk = _raw(fx.Int32(0))
            for j in range_constexpr(4):
                src_bf16x2 = _raw(fx.Vector.from_elements([h_dw[i][j]], fx.Int32).bitcast(fx.BFloat16))
                pk = rocdl.cvt_scalef32_pk_fp4_bf16(T.i32, pk, src_bf16x2, qs_raw, j)
            kb_in_kt = fx.Int32(i * 4) + lane_shr2_and3
            off = (
                fx.Int32(slot * (BM * KH_TILE))
                + a_row * fx.Int32(KH_TILE)
                + ((kb_in_kt * fx.Int32(16)) ^ mask)
                + lib * fx.Int32(4)
            )
            _scalar_store(s_aq_i32x1_tiles, off // fx.Int32(4), fx.Int32(pk), fx.Int32)
            scale_accum = scale_accum | (e8[i] << fx.Int32(i * 16))
        lane_tgt = lane_shr2_and3 * fx.Int32(16) + a_row
        off = fx.Int32(kt * 256) + lane_tgt * fx.Int32(4)
        _scalar_store(asc_i32_tiles, off // fx.Int32(4), scale_accum, fx.Int32)

    def issue_b_load_j(b_slot, K_C, j):
        v = (lane_div_16 * fx.Int32(256)) + (lane_mod_16 * fx.Int32(16))
        v = v + fx.Int32(K_C * 2048)
        for half in range_constexpr(2):
            r = fx.make_rmem_tensor(bq_reg_lay, fx.Int32)
            fx.copy(
                bq_copy_atom,
                fx.slice(bq_tiles, (None, (v + fx.Int32(half * 1024)) // fx.Int32(16))),
                r,
                soffset=b_load_s_base[j] // fx.Int32(4),
            )
            b_slot[j][half] = r.load()

    def issue_b_scale_load(bs_slot, K_C):
        v = ((lane_div_16 * fx.Int32(16)) + lane_mod_16) * fx.Int32(4)
        K_C_HI = K_C // 16
        imm = (K_C - K_C_HI * 16) * (kBS_stride_k0_dw * 4)
        for mw in range_constexpr(2):
            s_off = b_scale_s_base[mw] if K_C_HI == 0 else b_scale_s_base_hi[mw]
            r = fx.make_rmem_tensor(bscale_reg_lay, fx.Int32)
            fx.copy(
                bscale_copy_atom,
                fx.slice(bscale_tiles, (None, (v + fx.Int32(imm)) // fx.Int32(4))),
                r,
                soffset=s_off // fx.Int32(4),
            )
            bs_slot[mw] = r.load()[0]

    def issue_b_stage(kc):
        for j in range_constexpr(NJ):
            issue_b_load_j(b[kc], kc, j)
        issue_b_scale_load(b_scale_v[kc], kc)

    zero4 = fx.Vector.filled(4, 0.0, fx.Float32)

    def mfma_cluster(b_slot, a, sa, bs_slot, J, init):
        in_b = J // 2
        sb = bs_slot[J % 2]
        acc = zero4 if init else accm[J]
        accm[J] = rocdl.mfma_scale_f32_16x16x128_f8f6f4(
            T.f32x4, [a[0], b_slot[J][0], acc, 4, 4, 0, sa, in_b, sb]
        )
        accm[J] = rocdl.mfma_scale_f32_16x16x128_f8f6f4(
            T.f32x4, [a[1], b_slot[J][1], accm[J], 4, 4, 2, sa, 2 + in_b, sb]
        )

    # The weight stream needs only the expert id, so it starts before the sort's LDS-only rank and publish steps.
    for kc in range_constexpr(kStages):
        issue_b_stage(kc)
    rocdl.sched_barrier(0)
    head_hook()
    rocdl.sched_barrier(0)
    row_token = _global_i32_load(_lds_i32_tiles(sort_lds_ptr, _W_ROWS, BM), a_row)
    h_pro = [hidden_loads(kc, row_token) for kc in range(kStages)]
    h_pend = [hidden_loads(kStages + d, row_token) for d in range(_HPF)]
    rocdl.sched_barrier(0)
    for kc in range_constexpr(kStages):
        quantize_tile(h_pro[kc], kc, kc)

    for OFFSET in range_constexpr(kUnroll):
        K_C = kStages + OFFSET
        slot_b = OFFSET % kStages
        gpu.barrier()
        a_cur = issue_a_ds_read(OFFSET % kAStages)
        asc_cur = issue_a_scale_ds_read(OFFSET)
        h_v = h_pend[0]
        h_pend = h_pend[1:]
        if const_expr(OFFSET + _HPF < kUnroll):
            h_pend = h_pend + [hidden_loads(K_C + _HPF, row_token)]
        rocdl.sched_barrier(0)
        for J in range_constexpr(NJ):
            rocdl.sched_barrier(0)
            rocdl.s_setprio(1)
            mfma_cluster(b[slot_b], a_cur, asc_cur, b_scale_v[slot_b], J, init=(OFFSET == 0))
            rocdl.s_setprio(0)
            rocdl.sched_barrier(0)
            issue_b_load_j(b[slot_b], K_C, J)
            rocdl.sched_barrier(0)
        issue_b_scale_load(b_scale_v[slot_b], K_C)
        quantize_tile(h_v, K_C % kAStages, K_C)

    for S in range_constexpr(kStages):
        kt = KTP - kStages + S
        gpu.barrier()
        a_cur = issue_a_ds_read(kt % kAStages)
        asc_cur = issue_a_scale_ds_read(kt)
        for J in range_constexpr(NJ):
            mfma_cluster(b[kt % kStages], a_cur, asc_cur, b_scale_v[kt % kStages], J, init=False)

    gpu.barrier()

    acc_layout = fx.make_layout((BM, BN), (BN, 1))
    acc_copy_atom = fx.make_copy_atom(fx.UniversalCopy32b(), fx.Float32)
    acc_reg_lay = fx.make_layout(1, 1)
    acc_flat_tiles = fx.logical_divide(
        fx.make_view(fx.recast_iter(fx.Float32, lds_raw_ptr), fx.make_layout(BM * BN, 1)),
        fx.make_layout(1, 1),
    )

    def acc_store(idx, value):
        r = fx.make_rmem_tensor(acc_reg_lay, fx.Float32)
        r.store(fx.Vector.from_elements([fx.Float32(value)], fx.Float32))
        fx.copy_atom_call(acc_copy_atom, r, fx.slice(acc_flat_tiles, (None, idx)))

    def acc_load(idx):
        r = fx.make_rmem_tensor(acc_reg_lay, fx.Float32)
        fx.copy_atom_call(acc_copy_atom, fx.slice(acc_flat_tiles, (None, idx)), r)
        return r.load()[0]

    row_base = lane_div_16 * fx.Int32(4)
    for J in range_constexpr(NJ):
        col_local = wave * fx.Int32(W8) + fx.Int32((J // 2) * 16) + lane_mod_16
        lds_col = (fx.Int32(BN // 2) + col_local) if J % 2 == 1 else col_local
        vec = fx.Vector(accm[J])
        for v in range_constexpr(4):
            acc_store(_layout_idx(acc_layout, row_base + fx.Int32(v), lds_col), vec[v])
    gpu.barrier()

    tx_i32 = fx.Int32(gpu.thread_id("x"))
    m_lane = tx_i32 // fx.Int32(NTH)
    n_lane = tx_i32 % fx.Int32(NTH)
    wave_grp = n_lane // fx.Int32(4)
    kk = n_lane % fx.Int32(4)

    gate_vs = [None] * 8
    up_vs = [None] * 8
    for ee in range_constexpr(8):
        gate_col = wave_grp * fx.Int32(32) + (fx.Int32(8) * kk + fx.Int32(ee))
        gate_vs[ee] = acc_load(_layout_idx(acc_layout, m_lane, gate_col))
        up_vs[ee] = acc_load(_layout_idx(acc_layout, m_lane, fx.Int32(BN // 2) + gate_col))
    result = _silu_mul_batch(gate_vs, up_vs)

    local_max = _fabs_f32(result[0])
    for ee in range_constexpr(1, 8):
        local_max = local_max.maximumf(_fabs_f32(result[ee]))
    lm_i = _inline_dpp_quad_amax(fx.Int32(_raw(local_max).bitcast(T.i32)))
    e8m0, qscale = _e8m0_from_amax(fx.Float32(_raw(lm_i).bitcast(T.f32)))

    packed = _raw(fx.Int32(0))
    for w in range_constexpr(4):
        packed = rocdl.cvt_scalef32_pk_fp4_f32(
            T.i32, packed, _raw(result[2 * w]), _raw(result[2 * w + 1]), _raw(qscale), w
        )
    k_g2_half = k_half_for(_I)
    byte_pos = n_block_idx * fx.Int32(BN // 4) + wave_grp * fx.Int32(16) + kk * fx.Int32(4)
    store_off = _layout_idx(fx.make_layout((BM, k_g2_half), (k_g2_half, 1)), m_row + m_lane, byte_pos)
    _scalar_store(
        _global_scalar_tiles(arg_aqout, fx.Int32, 1 << 24),
        store_off // fx.Int32(4),
        fx.Int32(packed),
        fx.Int32,
    )

    # (chunk, ku, wave_grp, m_lane) -> dword index of stage 2's shuffled e8m0 scales; the chunk extent is a bound.
    ascaleout_layout = fx.make_layout((1 << 20, 2, 4, 16), (kas_per_chunk_dw_for(_I), 64, 16, 1))
    ascaleout_tiles = _global_scalar_tiles(arg_ascaleout, fx.Int8, 1 << 26)
    if kk == fx.Int32(0):
        grp = n_block_idx * fx.Int32(BN // 64) + wave_grp
        nb_old = grp >> fx.Int32(2)
        wg_old = grp & fx.Int32(3)
        ku = nb_old >> fx.Int32(1)
        ikxdl = nb_old & fx.Int32(1)
        dword_off = _layout_idx(ascaleout_layout, m_block_idx, ku, wg_old, m_lane)
        _scalar_store(ascaleout_tiles, dword_off * fx.Int32(4) + ikxdl * fx.Int32(2), e8m0, fx.Int8)


def _fold_stage1(n_tokens, n_blocks, xcd_contiguous):
    BM = _FBM
    MT = n_tokens * _TOPK
    NREP = (MT + _FT - 1) // _FT
    NNB = num_n_blocks_for(_N1, _FBN)
    GRID = n_blocks * NNB
    NDW = n_tokens * (_D // 2)  # ``out`` in i32 words
    NREP_Z = (NDW + GRID * _FT - 1) // (GRID * _FT)
    lds_bytes = _bm_constants(BM, _FBN, _FBK // 2, k_tiles_total_for(_D, _FBK))[3]

    @fx.struct
    class SharedStorage:
        raw: fx.Array[fx.Uint8, lds_bytes, 16]
        srt: fx.Array[fx.Uint8, _SORT_WORDS * 4, 16]

    @flyc.kernel(
        name=f"gemm1_a4w4_fold_m{n_tokens}{'_xcd' if xcd_contiguous else ''}", known_block_size=[_FT, 1, 1]
    )
    def gemm1_kernel_fold(
        # The leading kernargs arrive preloaded in SGPRs, so the topk loads that open the head wait on no s_load.
        arg_topk: fx.Int64,
        arg_topkw: fx.Int64,
        arg_moebuf: fx.Int64,
        arg_bq: fx.Int64,
        arg_bscale: fx.Int64,
        arg_hidden: fx.Int64,
        i32_ntok: fx.Int32,
        arg_eids: fx.Int64,
        arg_cumsum: fx.Int64,
        arg_aqout: fx.Int64,
        arg_ascaleout: fx.Int64,
        arg_stok: fx.Int64,
        arg_swgt: fx.Int64,
    ):
        _smem = fx.SharedAllocator().allocate(SharedStorage).peek()
        lds_raw_ptr = _smem.raw.ptr
        sort_ptr = _smem.srt.ptr
        tx_i32 = fx.Int32(gpu.thread_id("x"))
        bx_i32 = fx.Int32(gpu.block_id("x"))
        lane = tx_i32 % fx.Int32(64)
        wave = rocdl.readfirstlane(T.i32, tx_i32 // fx.Int32(64))
        # Keeps these kernarg loads in the entry batch: LLVM would sink each behind the head's tile check.
        pins = [_raw(fx.Int64(arg_bq)), _raw(fx.Int64(arg_bscale)), _raw(fx.Int32(i32_ntok))]
        llvm.InlineAsmOp(None, pins, "", ",".join(["s"] * len(pins)), has_side_effects=True)
        cnt_tiles = _lds_i32_tiles(sort_ptr, 0, _W_CNT)
        wt_tiles = _lds_i32_tiles(sort_ptr, _W_WT, 16)
        mi_tiles = _lds_i32_tiles(sort_ptr, _W_MISC, 16)
        rw_tiles = _lds_i32_tiles(sort_ptr, _W_ROWS, BM)
        st_tiles = _lds_i32_tiles(sort_ptr, _W_STOK, BM)
        wg_tiles = _lds_i32_tiles(sort_ptr, _W_WGT, BM)

        # Every workgroup sorts all routes itself: no grid-wide barrier. Pad routes read expert -1.
        tkw_regs = []
        tk_regs = []
        for r in range_constexpr(NREP):
            i = tx_i32 + fx.Int32(r * _FT)
            m = _ashr(i - fx.Int32(MT), 31)  # -1 iff i < MT
            tk_regs.append((_global_i32_at(arg_topk, i & m), m))
            tkw_regs.append(_global_i32_at(arg_topkw, i & m))
        mb_tiles = _global_scalar_tiles(arg_moebuf, fx.Int32, NDW)
        gtid = bx_i32 * fx.Int32(_FT) + tx_i32
        for rz in range_constexpr(NREP_Z):
            zi = gtid + fx.Int32(rz * GRID * _FT)
            if zi < fx.Int32(NDW):
                _scalar_store(mb_tiles, zi, fx.Int32(0), fx.Int32)
        for r in range_constexpr((_W_CNT + _FT - 1) // _FT):
            ci = tx_i32 + fx.Int32(r * _FT)
            if ci < fx.Int32(_W_CNT):
                _scalar_store(cnt_tiles, ci, fx.Int32(0), fx.Int32)
        tk_regs = [(tv & m) | (fx.Int32(-1) ^ m) for (tv, m) in tk_regs]
        gpu.barrier()
        for r in range_constexpr(NREP):
            if tx_i32 + fx.Int32(r * _FT) < fx.Int32(MT):
                _lds_add(fx.Int32(fx.ptrtoint(sort_ptr)), tk_regs[r], 1)
        gpu.barrier()

        def _block_scan(x):
            """Workgroup add-scan: x's inclusive scan within its wave, earlier waves' totals and the wave totals."""
            inc = fx.coop.warp_inclusive_scan(x, ReductionOp.ADD)
            gpu.barrier()
            if lane == fx.Int32(63):
                _scalar_store(wt_tiles, wave, inc, fx.Int32)
            gpu.barrier()
            w0 = _global_i32_load(wt_tiles, fx.Int32(0))
            w1 = _global_i32_load(wt_tiles, fx.Int32(1))
            w2 = _global_i32_load(wt_tiles, fx.Int32(2))
            w3 = _global_i32_load(wt_tiles, fx.Int32(3))
            pref = (
                (w0 & _ashr(fx.Int32(0) - wave, 31))
                + (w1 & _ashr(fx.Int32(1) - wave, 31))
                + (w2 & _ashr(fx.Int32(2) - wave, 31))
            )
            return inc, pref, w0, w1, w2, w3

        # Thread t owns expert t's padded block count and the last expert is added on: the expert offsets in blocks.
        cnt_a = _global_i32_load(cnt_tiles, tx_i32)
        nb_last = _udiv(_global_i32_load(cnt_tiles, fx.Int32(_NE - 1)) + fx.Int32(BM - 1), BM)
        nb_a = _udiv(cnt_a + fx.Int32(BM - 1), BM)
        inc, pref, w0, w1, w2, w3 = _block_scan(nb_a)
        t_last = w0 + w1 + w2 + w3
        excl_a = inc + pref - nb_a
        gpu.barrier()
        total_m_blocks = t_last + nb_last
        bound = total_m_blocks * fx.Int32(NNB)

        if bx_i32 < bound:
            if const_expr(xcd_contiguous):
                # Workgroups go to XCDs round-robin; XCD x runs the x-th contiguous run of the live tiles.
                xc = _umod(bx_i32, _NXCD)
                xr = _umod(bound, _NXCD)
                tile = (
                    xc * _udiv(bound, _NXCD)
                    + fx.Int32(arith.minsi(_raw(xc), _raw(xr)))
                    + _udiv(bx_i32, _NXCD)
                )
            else:
                tile = bx_i32
            mbi = tile // fx.Int32(NNB)
            nbi = tile % fx.Int32(NNB)
            if mbi >= excl_a:
                if mbi < excl_a + nb_a:
                    _scalar_store(mi_tiles, fx.Int32(0), tx_i32, fx.Int32)
                    _scalar_store(mi_tiles, fx.Int32(1), mbi - excl_a, fx.Int32)
            if tx_i32 == fx.Int32(0):
                if mbi >= t_last:
                    _scalar_store(mi_tiles, fx.Int32(0), fx.Int32(_NE - 1), fx.Int32)
                    _scalar_store(mi_tiles, fx.Int32(1), mbi - t_last, fx.Int32)
            # Rows past the expert's routes gather token n_tokens: out of bounds, read as zero.
            if tx_i32 < fx.Int32(BM):
                _scalar_store(rw_tiles, tx_i32, fx.Int32(n_tokens), fx.Int32)
                _scalar_store(st_tiles, tx_i32, fx.Int32(n_tokens), fx.Int32)
                _scalar_store(wg_tiles, tx_i32, fx.Int32(0), fx.Int32)
            gpu.barrier()
            fold_e = rocdl.readfirstlane(T.i32, _raw(_global_i32_load(mi_tiles, fx.Int32(0))))
            lo = _global_i32_load(mi_tiles, fx.Int32(1)) * fx.Int32(BM)

            def _rank_and_publish():
                # Rank this expert's routes and keep rows [lo, lo + BM).
                base = fx.Int32(0)
                for r in range_constexpr(NREP):
                    i = tx_i32 + fx.Int32(r * _FT)
                    x = _is_eq(tk_regs[r], fold_e)
                    inc2, p2, u0, u1, u2, u3 = _block_scan(x)
                    d = base + p2 + inc2 - x - lo
                    if x == fx.Int32(1):
                        if fx.Uint32(d) < fx.Uint32(BM):
                            tok = i // fx.Int32(_TOPK)
                            kk = i % fx.Int32(_TOPK)
                            _scalar_store(rw_tiles, d, tok, fx.Int32)
                            _scalar_store(st_tiles, d, tok | (kk << fx.Int32(_TOK_BITS)), fx.Int32)
                            _scalar_store(wg_tiles, d, tkw_regs[r], fx.Int32)
                    base = base + u0 + u1 + u2 + u3
                gpu.barrier()
                # The first n-block's workgroup publishes this m-block's slice of stage 2's sort tables.
                if nbi == fx.Int32(0):
                    stok_g = _global_scalar_tiles(arg_stok, fx.Int32, n_blocks * BM)
                    swgt_g = _global_scalar_tiles(arg_swgt, fx.Int32, n_blocks * BM)
                    seid_g = _global_scalar_tiles(arg_eids, fx.Int32, n_blocks)
                    if tx_i32 < fx.Int32(BM):
                        sp = mbi * fx.Int32(BM) + tx_i32
                        _scalar_store(stok_g, sp, _global_i32_load(st_tiles, tx_i32), fx.Int32)
                        _scalar_store(swgt_g, sp, _global_i32_load(wg_tiles, tx_i32), fx.Int32)
                    if tx_i32 == fx.Int32(0):
                        _scalar_store(seid_g, mbi, fold_e, fx.Int32)
                        if mbi == fx.Int32(0):
                            nv_g = _global_scalar_tiles(arg_cumsum, fx.Int32, 2)
                            _scalar_store(nv_g, fx.Int32(0), total_m_blocks * fx.Int32(BM), fx.Int32)
                            _scalar_store(nv_g, fx.Int32(1), fx.Int32(n_tokens), fx.Int32)

            _gemm1_body_fold(
                lds_raw_ptr,
                sort_ptr,
                fold_e,
                arg_bq,
                arg_bscale,
                arg_aqout,
                arg_ascaleout,
                arg_hidden,
                tile,
                lane,
                wave,
                i32_ntok,
                _rank_and_publish,
            )

    @flyc.jit
    def launch_gemm1_fold(
        arg_topk: fx.Int64,
        arg_topkw: fx.Int64,
        arg_moebuf: fx.Int64,
        arg_bq: fx.Int64,
        arg_bscale: fx.Int64,
        arg_hidden: fx.Int64,
        i32_ntok: fx.Int32,
        arg_eids: fx.Int64,
        arg_cumsum: fx.Int64,
        arg_aqout: fx.Int64,
        arg_ascaleout: fx.Int64,
        arg_stok: fx.Int64,
        arg_swgt: fx.Int64,
        i32_grid: fx.Int32,
        stream: fx.Stream,
    ):
        gemm1_kernel_fold(
            arg_topk,
            arg_topkw,
            arg_moebuf,
            arg_bq,
            arg_bscale,
            arg_hidden,
            i32_ntok,
            arg_eids,
            arg_cumsum,
            arg_aqout,
            arg_ascaleout,
            arg_stok,
            arg_swgt,
        ).launch(grid=(fx.Int64(i32_grid), 1, 1), block=(_FT, 1, 1), stream=stream)

    launch_gemm1_fold.compile_hints["llvm_options"] = {"amdgpu-kernarg-preload-count": 16}
    return launch_gemm1_fold


def _g2_spart_tile(block_1d_id, M0, N0):
    """Stage 2's (m-block, n-block) for a workgroup id: four interleaved groups, m-blocks walked in pairs."""
    gn = fx.Int32(4)
    n0 = fx.Int32(N0)
    m01c = fx.Int32(2)
    mn = M0 * n0
    group_size = _udiv(mn + gn - fx.Int32(1), gn)
    big_group_num = gn - (group_size * gn - mn)
    group_id_y = _udiv(block_1d_id, gn)
    group_id_x = block_1d_id - group_id_y * gn
    remap_a = group_id_x * group_size + group_id_y
    remap_b = group_id_x * group_size + big_group_num - group_id_x + group_id_y
    remap = (group_id_x <= big_group_num).select(remap_a, remap_b)
    idx_M0 = _udiv(remap, n0)
    idx_N0 = remap - idx_M0 * n0
    M0_full = _udiv(M0, m01c)
    M0_mod = M0 - M0_full * m01c
    M01_adapt = (idx_M0 < (M0 - M0_mod)).select(m01c, M0_mod)
    idx_M00 = _udiv(idx_M0, m01c)
    idx_M01 = idx_M0 - idx_M00 * m01c
    idx_local = idx_N0 + idx_M01 * n0
    N_out = _udiv(idx_local, M01_adapt)
    loc_mod = idx_local - N_out * M01_adapt
    return loc_mod + idx_M00 * m01c, N_out


def _atomic_prefetch(arg_stids, arg_sweights, m_row):
    """This thread's packed sorted ids and routing weights for the epilogue, loaded ahead of the GEMM."""
    m_lane = fx.Int32(gpu.thread_id("x")) // fx.Int32(_EPI_LANES)
    stids_base = _global_base_ptr1(arg_stids)
    sweights_base = _global_base_ptr1(arg_sweights)
    packed = []
    weight = []
    for mr in range_constexpr(_FBM // _EPI_ROWS):
        sorted_pos = m_row + fx.Int32(mr * _EPI_ROWS) + m_lane
        packed.append(llvm.load(T.i32, _gep1(stids_base, sorted_pos * fx.Int32(4)), invariant=True))
        weight.append(llvm.load(T.f32, _gep1(sweights_base, sorted_pos * fx.Int32(4)), invariant=True))
    return packed, weight


@flyc.jit
def _atomic_bf16_epilog(lds_acc_base_i32, accm, arg_out, n_block_idx, wave, lane, i32_M, packed, weight):
    """Rows scaled by their routing weight and added into ``out``, a pair of bf16 columns per atomic add."""
    BN = _FBN
    EPI_PASSES = BN // (2 * _EPI_LANES)
    lane_div_16 = lane // fx.Int32(16)
    lane_mod_16 = lane % fx.Int32(16)
    lds_base = _lds_ptr3(lds_acc_base_i32, fx.Int32(0))
    tx_i32 = fx.Int32(gpu.thread_id("x"))
    m_lane = tx_i32 // fx.Int32(_EPI_LANES)
    col_start = (tx_i32 % fx.Int32(_EPI_LANES)) * fx.Int32(2)
    out_base = _global_base_ptr1(arg_out)

    row_base = lane_div_16 * fx.Int32(4)
    for J in range_constexpr(4):
        col = wave * fx.Int32(BN // 4) + fx.Int32(J * 16) + lane_mod_16
        vec = fx.Vector(accm[J])
        for v in range_constexpr(4):
            idx = (row_base + fx.Int32(v)) * fx.Int32(BN) + col
            llvm.StoreOp(_raw(vec[v]), _gep3(lds_base, idx * fx.Int32(4)))
    gpu.barrier()
    # Pinning the prefetched ids and weights here keeps LLVM from sinking their loads past the barrier.
    pin_all = [_raw(w) for w in weight] + [_raw(p) for p in packed]
    llvm.InlineAsmOp(None, pin_all, "", ",".join(["v"] * len(pin_all)), has_side_effects=True)

    pk_all = []
    for mr in range_constexpr(_FBM // _EPI_ROWS):
        row_in_block = fx.Int32(mr * _EPI_ROWS) + m_lane
        pk_row = []
        for s in range_constexpr(EPI_PASSES):
            idx0 = row_in_block * fx.Int32(BN) + col_start + fx.Int32(s * 2 * _EPI_LANES)
            v2 = fx.Vector(llvm.load(T.vec(2, T.f32), _gep3(lds_base, idx0 * fx.Int32(4))))
            pk_row.append(
                fx.Vector.from_elements([v2[0] * weight[mr], v2[1] * weight[mr]], fx.Float32).to(fx.BFloat16)
            )
        pk_all.append(pk_row)
    pk_flat = [_raw(pk) for row in pk_all for pk in row]
    llvm.InlineAsmOp(None, pk_flat, "", ",".join(["v"] * len(pk_flat)), has_side_effects=True)

    for mr in range_constexpr(_FBM // _EPI_ROWS):
        token_id = packed[mr] & fx.Int32((1 << _TOK_BITS) - 1)
        if token_id < i32_M:
            row_base_addr = token_id * fx.Int32(_D) + n_block_idx * fx.Int32(BN) + col_start
            for s in range_constexpr(EPI_PASSES):
                llvm.AtomicRMWOp(
                    llvm.AtomicBinOp.fadd,
                    _gep1(out_base, (row_base_addr + fx.Int32(s * 2 * _EPI_LANES)) * fx.Int32(2)),
                    _raw(pk_all[mr][s]),
                    llvm.AtomicOrdering.monotonic,
                    syncscope="agent",
                    alignment=4,
                )


@flyc.jit
def _gemm2_body(
    lds_raw_ptr,
    arg_ascale,
    arg_bq,
    arg_bscale,
    arg_stids,
    arg_sweights,
    i32_M,
    arg_out,
    m_block_idx,
    n_block_idx,
    lane,
    wave,
    e,
):
    """Down GEMM of one (m-block, n-block) tile over the whole inter dim, every k-tile's A already in LDS."""
    BM = _FBM
    BN = _FBN
    KH_TILE = _FBK // 2
    KT = k_tiles_total_for(_I, _FBK)
    K_HALF = k_half_for(_I)
    slot_bytes = saq_slot_bytes(BM, KH_TILE)
    kAS_per_chunk_dw = kas_per_chunk_dw_for(_I)
    kBS_stride_n0_dw = kbs_stride_n0_dw_for(_I)
    m_row = m_block_idx * fx.Int32(BM)

    ascale_rsrc = _buffer_rsrc(arg_ascale, _NO_BOUND)
    bq_rsrc = _buffer_rsrc(arg_bq, bq_bytes_for(_NE, _D, _I))
    bscale_rsrc = _buffer_rsrc(arg_bscale, bscale_bytes_for(_NE, _D, _I))

    # LDS: the A tiles, then the f32 accumulator.
    saq_base_i32 = fx.Int32(fx.ptrtoint(lds_raw_ptr))
    lds_acc_base_i32 = saq_base_i32 + fx.Int32(KT * slot_bytes)

    lane_div_16 = lane // fx.Int32(16)
    lane_mod_16 = lane % fx.Int32(16)

    b_load_s_base = []
    for j in range_constexpr(4):
        v = (
            e * fx.Int32(_D) + n_block_idx * fx.Int32(BN) + wave * fx.Int32(BN // 4) + fx.Int32(j * 16)
        ) * fx.Int32(K_HALF)
        b_load_s_base.append(rocdl.readfirstlane(T.i32, v))

    mni_base = n_block_idx * fx.Int32(BN // 16 // 2) + wave * fx.Int32(BN // 64 // 2)
    b_scale_s_base = []
    for mw in range_constexpr(2):
        v = (
            e * fx.Int32(kbs_per_expert_dw_for(_D, _I))
            + (mni_base + fx.Int32(mw)) * fx.Int32(kBS_stride_n0_dw)
        ) * fx.Int32(4)
        b_scale_s_base.append(rocdl.readfirstlane(T.i32, v))

    a_scale_s_base = rocdl.readfirstlane(T.i32, m_block_idx * fx.Int32(kAS_per_chunk_dw * 4))
    v_voff_scale = ((lane_div_16 * fx.Int32(16)) + lane_mod_16) * fx.Int32(4)

    def load_a_scale_tile(kt):
        return buffer_load(
            ascale_rsrc,
            (v_voff_scale + fx.Int32(kt * 256)) // fx.Int32(4),
            vec_width=1,
            dtype=T.i32,
            cache_modifier=0,
            soffset_bytes=a_scale_s_base,
        )

    def load_b_scale_tile(kt):
        out = [None, None]
        for mw in range_constexpr(2):
            out[mw] = buffer_load(
                bscale_rsrc,
                (v_voff_scale + fx.Int32(kt * (kBS_stride_k0_dw * 4))) // fx.Int32(4),
                vec_width=1,
                dtype=T.i32,
                cache_modifier=_NT,
                soffset_bytes=b_scale_s_base[mw],
            )
        return out

    def load_b_tile(kt):
        v_voff_b = (lane_div_16 * fx.Int32(256)) + (lane_mod_16 * fx.Int32(16)) + fx.Int32(kt * 2048)
        out = [[None, None] for _ in range(4)]
        for j in range_constexpr(4):
            for half in range_constexpr(2):
                frag = buffer_load(
                    bq_rsrc,
                    (v_voff_b + fx.Int32(half * 1024)) // fx.Int32(4),
                    vec_width=4,
                    dtype=T.i32,
                    cache_modifier=_NT,
                    soffset_bytes=b_load_s_base[j],
                )
                out[j][half] = fx.Vector(frag)
        return out

    def issue_a_ds_read(slot):
        mask = _lds_swizzle_mask(lane_mod_16)
        base_ptr = _lds_ptr3(saq_base_i32, fx.Int32(0))
        a = [None, None]
        for k in range_constexpr(2):
            lds_col = (lane_div_16 * fx.Int32(16) + fx.Int32(k * 64)) ^ mask
            byte_off = fx.Int32(slot * slot_bytes) + lane_mod_16 * fx.Int32(KH_TILE) + lds_col
            a[k] = llvm.load(T.vec(4, T.i32), _gep3(base_ptr, byte_off))
        return a

    zero4 = fx.Vector.filled(4, 0.0, fx.Float32)
    accm = [None] * 4

    def mfma_cluster(b_tile, a, sa, b_scale_slot, init):
        for J in range_constexpr(4):
            in_b = J % 2
            sb = b_scale_slot[J // 2]
            acc = zero4 if init else accm[J]
            accm[J] = rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                T.f32x4, [a[0], b_tile[J][0], acc, 4, 4, 0, sa, in_b, sb]
            )
            accm[J] = rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                T.f32x4, [a[1], b_tile[J][1], accm[J], 4, 4, 2, sa, 2 + in_b, sb]
            )

    a_scale_v = [load_a_scale_tile(kt) for kt in range_constexpr(KT)]
    b_scale_v = [load_b_scale_tile(kt) for kt in range_constexpr(KT)]
    b = [load_b_tile(kt) for kt in range_constexpr(KT)]
    packed, weight = _atomic_prefetch(arg_stids, arg_sweights, m_row)
    for kt in range_constexpr(KT):
        gpu.barrier()
        mfma_cluster(b[kt], issue_a_ds_read(kt), a_scale_v[kt], b_scale_v[kt], init=(kt == 0))
    _atomic_bf16_epilog(lds_acc_base_i32, accm, arg_out, n_block_idx, wave, lane, i32_M, packed, weight)


@functools.cache
def _fold_stage2(xcd_major):
    BM = _FBM
    KH_TILE = _FBK // 2
    KT = k_tiles_total_for(_I, _FBK)
    K_HALF = k_half_for(_I)
    slot_bytes = saq_slot_bytes(BM, KH_TILE)
    num_n_blocks = num_n_blocks_for(_D, _FBN)
    n_load_waves, rows_per_wave, _ = tiling(BM)

    @fx.struct
    class SharedStorage:
        raw: fx.Array[fx.Uint8, lds_acc_bytes_for(BM, _FBN) + KT * slot_bytes, 16]

    @flyc.kernel(name=f"gemm2_a4w4_fold{'_xm' if xcd_major else ''}", known_block_size=[_FT, 1, 1])
    def gemm2_kernel(
        arg_aq: fx.Int64,
        arg_ascale: fx.Int64,
        arg_bq: fx.Int64,
        arg_bscale: fx.Int64,
        arg_eids: fx.Int64,
        arg_cumsum: fx.Int64,
        arg_stids: fx.Int64,
        arg_sweights: fx.Int64,
        i32_M: fx.Int32,
        arg_out: fx.Int64,
    ):
        tx_i32 = fx.Int32(gpu.thread_id("x"))
        bx_i32 = fx.Int32(gpu.block_id("x"))
        lane = tx_i32 % fx.Int32(64)
        wave = rocdl.readfirstlane(T.i32, tx_i32 // fx.Int32(64))
        aq_rsrc = _buffer_rsrc(arg_aq, _NO_BOUND)
        lds_raw_ptr = fx.SharedAllocator().allocate(SharedStorage).peek().raw.ptr
        saq_base_i32 = fx.Int32(fx.ptrtoint(lds_raw_ptr))

        def _run_tile(m_block, n_block, e):
            # Every k-tile of the block's A goes to LDS up front, by the waves that own its rows.
            if wave < fx.Int32(n_load_waves):
                lds_row = wave * fx.Int32(rows_per_wave)
                car = m_block * fx.Int32(BM) + lds_row + (lane // fx.Int32(8))
                for slot in range_constexpr(KT):
                    _issue_a_load_lds(
                        aq_rsrc,
                        saq_base_i32,
                        slot,
                        slot,
                        car,
                        lane,
                        slot_bytes,
                        lds_row,
                        KH_TILE=KH_TILE,
                        k_half=K_HALF,
                    )
            rocdl.sched_barrier(0)
            llvm.InlineAsmOp(None, [_raw(e)], "", "s", has_side_effects=True)
            _gemm2_body(
                lds_raw_ptr,
                arg_ascale,
                arg_bq,
                arg_bscale,
                arg_stids,
                arg_sweights,
                i32_M,
                arg_out,
                m_block,
                n_block,
                lane,
                wave,
                e,
            )

        if const_expr(xcd_major):
            # Workgroup bx runs on XCD bx % _NXCD, which owns every _NXCD-th m-block and walks each one's n-blocks
            # in turn, so an m-block's activations are read through one L2. The launcher's m-block count must be a
            # multiple of _NXCD for every tile to be covered.
            xm_x = bx_i32 % fx.Int32(_NXCD)
            xm_l = bx_i32 // fx.Int32(_NXCD)
            xm_j = _udiv(xm_l, num_n_blocks)
            xm_n = xm_l - xm_j * fx.Int32(num_n_blocks)
            xm_m = xm_j * fx.Int32(_NXCD) + xm_x
            rows = llvm.load(T.i32, _global_ptr1(arg_cumsum, fx.Int32(0)))
            e = rocdl.readfirstlane(T.i32, llvm.load(T.i32, _global_ptr1(arg_eids, xm_m * fx.Int32(4))))
            rows = rocdl.readfirstlane(T.i32, rows)
            if xm_m * fx.Int32(BM) < rows:
                _run_tile(xm_m, xm_n, e)
        else:
            total_m_blocks = _udiv(llvm.load(T.i32, _global_ptr1(arg_cumsum, fx.Int32(0))), BM)
            if bx_i32 < total_m_blocks * fx.Int32(num_n_blocks):
                sp_m, sp_n = _g2_spart_tile(bx_i32, total_m_blocks, num_n_blocks)
                sp_e = llvm.load(T.i32, _global_ptr1(arg_eids, sp_m * fx.Int32(4)), invariant=True)
                _run_tile(sp_m, sp_n, rocdl.readfirstlane(T.i32, sp_e))

    @flyc.jit
    def launch_gemm2(
        arg_aq: fx.Int64,
        arg_ascale: fx.Int64,
        arg_bq: fx.Int64,
        arg_bscale: fx.Int64,
        arg_eids: fx.Int64,
        arg_cumsum: fx.Int64,
        arg_stids: fx.Int64,
        arg_sweights: fx.Int64,
        i32_M: fx.Int32,
        arg_out: fx.Int64,
        i32_m_blocks: fx.Int32,
        stream: fx.Stream,
    ):
        gemm2_kernel(
            arg_aq,
            arg_ascale,
            arg_bq,
            arg_bscale,
            arg_eids,
            arg_cumsum,
            arg_stids,
            arg_sweights,
            i32_M,
            arg_out,
        ).launch(
            grid=(fx.Int64(i32_m_blocks) * fx.Int64(num_n_blocks), 1, 1), block=(_FT, 1, 1), stream=stream
        )

    launch_gemm2.compile_hints["llvm_options"] = {
        "enable-post-misched": False,
        "amdgpu-kernarg-preload-count": 16,
    }
    return launch_gemm2


@functools.cache
def _fold_plan(n_tokens):
    """Both launchers, the stage-1 grid, the m-block count and the scratch layout for n_tokens."""
    items = n_tokens * _TOPK
    active = min(_NE, items)
    max_sorted = (items + active * (_FBM - 1) + _FBM - 1) // _FBM * _FBM
    n_blocks = max_sorted // _FBM
    # Stage 2's XCD-major order launches whole groups of _NXCD m-blocks; it reads the expert id of the padding
    # m-blocks (past n_blocks, inside the expert-id slot's alignment) before discarding them.
    xcd_contiguous, xcd_major = _FOLD[n_tokens]
    n_blocks2 = (n_blocks + _NXCD - 1) // _NXCD * _NXCD if xcd_major else n_blocks
    assert n_blocks2 * 4 <= (n_blocks * 4 + _ALIGN - 1) // _ALIGN * _ALIGN
    grid1 = n_blocks * num_n_blocks_for(_N1, _FBN)
    scale_cols = _I // 32
    scale_rows = (max_sorted * 64 + scale_cols - 1) // scale_cols
    scale_rows = (scale_rows + 31) // 32 * 32
    sizes = (
        max_sorted * 4,
        max_sorted * 4,
        n_blocks * 4,
        2 * 4,
        max_sorted * (_I // 2),
        scale_rows * scale_cols,
    )
    offsets = []
    total = 0
    for size in sizes:
        offsets.append(total)
        total += (size + _ALIGN - 1) // _ALIGN * _ALIGN
    stage1 = _fold_stage1(n_tokens, n_blocks, xcd_contiguous)
    return stage1, _fold_stage2(xcd_major), grid1, n_blocks2, total, tuple(offsets)


def _fold_run(hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, out):
    n_tokens = hidden_states.shape[0]
    stage1, stage2, grid1, n_blocks2, ws_bytes, offsets = _fold_plan(n_tokens)
    ws = torch.empty(ws_bytes, dtype=torch.uint8, device=hidden_states.device)
    base = ws.data_ptr()
    sids, swts, seids, nvalid, inter, iscale = (base + o for o in offsets)
    stream = torch.cuda.current_stream(hidden_states.device).cuda_stream
    stage1(
        topk_ids.data_ptr(),
        topk_weights.data_ptr(),
        out.data_ptr(),
        w1.data_ptr(),
        w1_scale.data_ptr(),
        hidden_states.data_ptr(),
        n_tokens,
        seids,
        nvalid,
        inter,
        iscale,
        sids,
        swts,
        grid1,
        stream,
    )
    stage2(
        inter,
        iscale,
        w2.data_ptr(),
        w2_scale.data_ptr(),
        seids,
        nvalid,
        sids,
        swts,
        n_tokens,
        out.data_ptr(),
        n_blocks2,
        stream,
    )


def run(
    *,
    hidden_states,
    w1,
    w2,
    topk_weights,
    topk_ids,
    w1_scale,
    w2_scale,
    activation,
    quant_type,
    doweight_stage1,
    gate_mode,
    act_quant,
    expert_mask,
    beta,
    linear_beta,
    out_dtype,
    out,
):
    n_tokens = hidden_states.shape[0]
    launch = _plan(n_tokens)
    if launch is not None:
        P = _DECODE[n_tokens][2]
        inter = (
            torch.empty((n_tokens * _TOPK, _I), dtype=torch.bfloat16, device=hidden_states.device)
            if P == 1
            else torch.empty((n_tokens * _TOPK * P, _N1), dtype=torch.bfloat16, device=hidden_states.device)
        )
        launch(
            hidden_states.data_ptr(),
            topk_ids.data_ptr(),
            w1.data_ptr(),
            w1_scale.data_ptr(),
            w2.data_ptr(),
            w2_scale.data_ptr(),
            topk_weights.data_ptr(),
            out.data_ptr(),
            inter.data_ptr(),
            torch.cuda.current_stream(hidden_states.device).cuda_stream,
        )
        return
    if (
        activation == "silu"
        and quant_type == "per_1x32"
        and not doweight_stage1
        and gate_mode == "separated"
        and expert_mask is None
        and beta is None
        and linear_beta is None
        and act_quant == 4
        and out.dtype == torch.bfloat16
        and out.is_contiguous()
        and topk_ids.dtype == torch.int32
        and topk_weights.dtype == torch.float32
        and topk_ids.is_contiguous()
        and topk_weights.is_contiguous()
        and out_dtype in (None, torch.bfloat16)
        and hidden_states.dtype == torch.bfloat16
    ):
        shuffled = bool(getattr(w1, "is_shuffled", False) and getattr(w2, "is_shuffled", False))
        if n_tokens in _FOLD and shuffled:
            _fold_run(hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, out)
            return
        plan = _aiter_plan(n_tokens, w1.dtype, shuffled)
        if plan is not None:
            _aiter_into_out(plan, hidden_states, w1, w2, topk_weights, topk_ids, w1_scale, w2_scale, out)
            return
    result = fused_moe_baseline(
        hidden_states,
        w1,
        w2,
        topk_weights,
        topk_ids,
        expert_mask=expert_mask,
        activation=activation,
        quant_type=quant_type,
        doweight_stage1=doweight_stage1,
        w1_scale=w1_scale,
        w2_scale=w2_scale,
        beta=beta,
        linear_beta=linear_beta,
        gate_mode=gate_mode,
        out_dtype=out_dtype,
        act_quant=act_quant,
    )
    out.copy_(result)
